package bazi

import (
	"encoding/json"
	"fmt"
	"os"
	"testing"
	"time"

	"liki-engine/internal/engine/ganzhi"
)

// goldenChecks controls which optional fields verifyBaziGoldenCase asserts.
type goldenChecks struct {
	MingGong      bool // 命宫
	ShenGong      bool // 身宫
	TaiYuan       bool // 胎元
	QiYunMonthDay bool // 起运月+起运日（分钟级精度）
}

// baziGoldenCase is one case from testdata/bazi_golden*.json, generated by
// lunar-typescript (6tail) — the authoritative bazi golden source.
type baziGoldenCase struct {
	Name    string  `json:"name"`
	Solar   string  `json:"solar"`
	TZ      float64 `json:"tz"`
	Lon     float64 `json:"lon"`
	Gender  string  `json:"gender"`
	Pillars struct {
		Nian string `json:"nian"`
		Yue  string `json:"yue"`
		Ri   string `json:"ri"`
		Shi  string `json:"shi"`
	} `json:"pillars"`
	DaYun struct {
		StartYearAfter  int      `json:"start_year_after"`
		StartMonthAfter int      `json:"start_month_after"`
		StartDayAfter   int      `json:"start_day_after"`
		Forward         bool     `json:"forward"`
		Steps           []string `json:"steps"`
	} `json:"da_yun"`
	SanYuan struct {
		TaiYuan  string `json:"tai_yuan"`
		MingGong string `json:"ming_gong"`
		ShenGong string `json:"shen_gong"`
	} `json:"san_yuan"`
}

func loadBaziGoldenFile(t *testing.T, filename string) []baziGoldenCase {
	t.Helper()
	b, err := os.ReadFile(filename)
	if err != nil {
		t.Fatalf("read golden %s: %v", filename, err)
	}
	var cases []baziGoldenCase
	if err := json.Unmarshal(b, &cases); err != nil {
		t.Fatalf("parse golden %s: %v", filename, err)
	}
	return cases
}

func verifyBaziGoldenCase(t *testing.T, gc baziGoldenCase, checks goldenChecks) {
	t.Helper()
	tt, err := time.ParseInLocation("2006-01-02T15:04:05", gc.Solar, time.FixedZone("CST", 8*3600))
	if err != nil {
		t.Fatalf("parse solar %q: %v", gc.Solar, err)
	}
	g := ganzhi.Male
	if gc.Gender == "female" {
		g = ganzhi.Female
	}
	c := ComputeChart(tt, tt, g)
	fc := ComputeFullChart(c)

	// 四柱
	p := fmt.Sprintf("%s%s %s%s %s%s %s%s",
		c.Nian.Gan, c.Nian.Zhi, c.Yue.Gan, c.Yue.Zhi,
		c.Ri.Gan, c.Ri.Zhi, c.Shi.Gan, c.Shi.Zhi)
	want := fmt.Sprintf("%s %s %s %s", gc.Pillars.Nian, gc.Pillars.Yue, gc.Pillars.Ri, gc.Pillars.Shi)
	if p != want {
		t.Errorf("四柱 = %s, want %s", p, want)
	}

	// 大运方向
	if (c.DaYun.Direction == "顺排") != gc.DaYun.Forward {
		t.Errorf("大运方向顺排 = %v, want %v", c.DaYun.Direction == "顺排", gc.DaYun.Forward)
	}
	if checks.QiYunMonthDay {
		// 起运精确年/月/日（对齐 lunar）。海外用例（tz≠8）受节气时刻分钟差
		// （VSOP87 精确 vs lunar 近似）跨时辰边界影响，年/月偏差不得超过 1。
		if gc.TZ == 8 {
			if c.DaYun.StartYearAfter != gc.DaYun.StartYearAfter {
				t.Errorf("起运年 = %d, want %d", c.DaYun.StartYearAfter, gc.DaYun.StartYearAfter)
			}
			if c.DaYun.StartMonthAfter != gc.DaYun.StartMonthAfter {
				t.Errorf("起运月 = %d, want %d", c.DaYun.StartMonthAfter, gc.DaYun.StartMonthAfter)
			}
			if c.DaYun.StartDayAfter != gc.DaYun.StartDayAfter {
				t.Errorf("起运日 = %d, want %d", c.DaYun.StartDayAfter, gc.DaYun.StartDayAfter)
			}
		} else {
			if absInt(c.DaYun.StartYearAfter-gc.DaYun.StartYearAfter) > 1 ||
				absInt(c.DaYun.StartMonthAfter-gc.DaYun.StartMonthAfter) > 1 {
				t.Errorf("海外起运年月偏离过大: got %d年%d月 want %d年%d月",
					c.DaYun.StartYearAfter, c.DaYun.StartMonthAfter,
					gc.DaYun.StartYearAfter, gc.DaYun.StartMonthAfter)
			}
		}
	} else {
		// 起运年（精确对齐 lunar，无 ±1；不查月/日、无海外容差）
		if c.DaYun.StartYearAfter != gc.DaYun.StartYearAfter {
			t.Errorf("起运年 = %d, want %d", c.DaYun.StartYearAfter, gc.DaYun.StartYearAfter)
		}
	}
	// 大运全步骤
	if len(c.DaYun.Steps) != len(gc.DaYun.Steps) {
		t.Errorf("大运步数 = %d, want %d", len(c.DaYun.Steps), len(gc.DaYun.Steps))
	} else {
		for si := range gc.DaYun.Steps {
			gs := c.DaYun.Steps[si].Gan.String() + c.DaYun.Steps[si].Zhi.String()
			if gs != gc.DaYun.Steps[si] {
				t.Errorf("大运[%d] = %s, want %s", si, gs, gc.DaYun.Steps[si])
				break
			}
		}
	}

	// 三元（命宫/身宫/胎元）
	if checks.MingGong {
		mg := fc.SanYuan.MingGong.Gan.String() + fc.SanYuan.MingGong.Zhi.String()
		if mg != gc.SanYuan.MingGong {
			t.Errorf("命宫 = %s, want %s", mg, gc.SanYuan.MingGong)
		}
	}
	if checks.ShenGong {
		sg := fc.SanYuan.ShenGong.Gan.String() + fc.SanYuan.ShenGong.Zhi.String()
		if sg != gc.SanYuan.ShenGong {
			t.Errorf("身宫 = %s, want %s", sg, gc.SanYuan.ShenGong)
		}
	}
	if checks.TaiYuan {
		ty := fc.SanYuan.TaiYuan.Gan.String() + fc.SanYuan.TaiYuan.Zhi.String()
		if ty != gc.SanYuan.TaiYuan {
			t.Errorf("胎元 = %s, want %s", ty, gc.SanYuan.TaiYuan)
		}
	}
}

func absInt(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
